import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 반제 처리로 만드는 전표의 원천 구분은 MANUAL, 증빙 유형은 통장, 상태는 승인이다.
const SETTLE_SOURCE_TYPE = 'MANUAL';
const SETTLE_EVIDENCE_TYPE = '통장';
const SETTLE_VOUCHER_STATUS = '승인';
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

@Controller('api/v1')
export class FnSfr00703Controller {
  @Get('/bank-transactions')
  async listBankTransactions(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const query = checks.queryOf(req.query);
    const fromDate = query['fromDate'];
    const toDate = query['toDate'];
    if (typeof fromDate !== 'string' || !DATE_PATTERN.test(fromDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    if (typeof toDate !== 'string' || !DATE_PATTERN.test(toDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 종료일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    let accountId: string | null = null;
    const rawAccount = query['partnerAccountId'];
    if (rawAccount !== undefined && rawAccount !== null && rawAccount !== '') {
      if (!/^\d+$/.test(String(rawAccount))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '거래처 계좌 값이 올바르지 않습니다.');
      }
      accountId = String(rawAccount);
    }
    let processingType: string | null = null;
    const rawType = query['processingType'];
    if (rawType !== undefined && rawType !== null && rawType !== '') {
      if (!['미처리', '자동전표', '예외', '반제'].includes(String(rawType))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '처리 구분 값이 올바르지 않습니다.');
      }
      processingType = String(rawType);
    }
    const rawPage = query['page'];
    const rawSize = query['size'];
    let page = 0;
    let size = 20;
    if (rawPage !== undefined && rawPage !== null && rawPage !== '') {
      page = Number(rawPage);
      if (!Number.isInteger(page) || page < 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
      }
    }
    if (rawSize !== undefined && rawSize !== null && rawSize !== '') {
      size = Number(rawSize);
      if (!Number.isInteger(size) || size < 1) {
        throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
      }
    }
    if (size > 200) {
      size = 200;
    }
    return transaction(async (db) => {
      const where = `
        transaction_at >= CAST(:fromDate AS date)
        AND transaction_at < CAST(:toDate AS date) + 1
        AND (CAST(:accountId AS bigint) IS NULL OR partner_account_id = CAST(:accountId AS bigint))
        AND (CAST(:processingType AS text) IS NULL OR processing_type = CAST(:processingType AS text))`;
      const filter = { fromDate, toDate, accountId, processingType };
      const counted = await db.query(
        `SELECT COUNT(*) AS "total" FROM bank_transaction WHERE ${where}`,
        filter,
      );
      const total = Number(counted[0]['total']);
      const items = await db.query(
        `SELECT bank_transaction_id AS "bankTransactionId",
          transaction_at AS "transactionAt",
          deposit_amount AS "depositAmount",
          withdrawal_amount AS "withdrawalAmount",
          summary AS "summary",
          counterparty_name AS "counterpartyName",
          processing_type AS "processingType"
        FROM bank_transaction
        WHERE ${where}
        ORDER BY transaction_at DESC, bank_transaction_id DESC
        LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { ...filter, size, offset: page * size },
      );
      return { items, page, size, total };
    });
  }

  @Post('/bank-transactions/:bankTransactionId/settle')
  @HttpCode(200)
  async settleBankTransaction(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const data = checks.inputOf(req.body);
    const id = req.params['bankTransactionId'];
    if (!/^\d+$/.test(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '거래내역 ID가 올바르지 않습니다.');
    }
    const targets = data['settlementTargetIds'];
    if (!Array.isArray(targets)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '반제할 항목 목록을 보내 주세요.');
    }
    if (targets.length === 0) {
      throw new ApiError(422, 'SETTLEMENT_TARGET_INVALID', '반제 대상을 선택해 주세요.');
    }
    for (const target of targets) {
      if (!/^\d+$/.test(String(target))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '반제 대상 ID가 올바르지 않습니다.');
      }
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT processing_type AS "processingType"
        FROM bank_transaction
        WHERE bank_transaction_id = CAST(:id AS bigint)
        FOR UPDATE`,
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'BANK_TRANSACTION_NOT_FOUND', '거래내역을 찾을 수 없습니다.');
      }
      if (rows[0]['processingType'] !== '예외') {
        throw new ApiError(409, 'BANK_TRANSACTION_ALREADY_PROCESSED', '이미 처리된 거래내역이거나 반제 대상이 아닙니다.');
      }
      const vouchers = await db.query(
        `INSERT INTO journal_voucher (
          voucher_date, evidence_type, source_type, status,
          debit_total, credit_total, created_at, updated_at
        )
        SELECT CAST(transaction_at AS date), :evidenceType, :sourceType, :status,
          COALESCE(deposit_amount, 0) + COALESCE(withdrawal_amount, 0),
          COALESCE(deposit_amount, 0) + COALESCE(withdrawal_amount, 0),
          now(), now()
        FROM bank_transaction
        WHERE bank_transaction_id = CAST(:id AS bigint)
        RETURNING journal_voucher_id AS "journalVoucherId"`,
        {
          id,
          evidenceType: SETTLE_EVIDENCE_TYPE,
          sourceType: SETTLE_SOURCE_TYPE,
          status: SETTLE_VOUCHER_STATUS,
        },
      );
      const updated = await db.query(
        `UPDATE bank_transaction
        SET processing_type = '반제',
          journal_voucher_id = CAST(:voucherId AS bigint),
          processed_by_id = CAST(:userId AS bigint),
          processed_at = now(),
          updated_at = now()
        WHERE bank_transaction_id = CAST(:id AS bigint)
        RETURNING bank_transaction_id AS "bankTransactionId", processing_type AS "processingType"`,
        { id, voucherId: String(vouchers[0]['journalVoucherId']), userId: user.id },
      );
      return updated[0];
    });
  }
}

