import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const TYPES: [string, string][] = [
  ['미처리', '미처리'],
  ['자동전표', '자동전표'],
  ['예외', '예외'],
  ['반제', '반제'],
];

function today(): string {
  return new Date().toISOString().slice(0, 10);
}

function monthStart(): string {
  return today().slice(0, 8) + '01';
}

export default function FnSfr00703Page({ role, notify }: PageProps) {
  const [fromDate, setFromDate] = useState<string>(monthStart());
  const [toDate, setToDate] = useState<string>(today());
  const [accountId, setAccountId] = useState<number | string>('');
  const [processingType, setProcessingType] = useState<string>('');
  const [applied, setApplied] = useState<Row>({ fromDate: monthStart(), toDate: today() });
  const [pageNo, setPageNo] = useState<number>(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [settling, setSettling] = useState<Row | null>(null);
  const [targetText, setTargetText] = useState<string>('');

  const list = useData<Page>(
    () => call<Page>('GET', '/bank-transactions', role, undefined, { ...applied, page: pageNo, size: 20 }),
    [applied, pageNo],
  );
  const pending = useData<Page>(
    () =>
      call<Page>('GET', '/bank-transactions', role, undefined, {
        fromDate: applied['fromDate'],
        toDate: applied['toDate'],
        processingType: '예외',
        page: 0,
        size: 5,
      }),
    [applied],
  );

  function search() {
    if (!fromDate || !toDate) {
      notify('조회 기간을 입력해 주세요.');
      return;
    }
    setPageNo(0);
    setApplied({ fromDate, toDate, partnerAccountId: accountId, processingType });
  }

  function reset() {
    setFromDate(monthStart());
    setToDate(today());
    setAccountId('');
    setProcessingType('');
    setPageNo(0);
    setApplied({ fromDate: monthStart(), toDate: today() });
  }

  function openSettle(row: Row) {
    setTargetText('');
    setSettling(row);
  }

  async function settle() {
    if (!settling) {
      return;
    }
    const ids = targetText
      .split(',')
      .map((s) => s.trim())
      .filter((s) => s !== '');
    if (ids.length === 0) {
      throw new Error('반제할 채권·채무 항목 ID를 입력해 주세요.');
    }
    if (ids.some((s) => !/^\d+$/.test(s))) {
      throw new Error('항목 ID는 쉼표로 구분한 숫자로 입력해 주세요.');
    }
    await call('POST', `/bank-transactions/${settling['bankTransactionId']}/settle`, role, {
      settlementTargetIds: ids.map((s) => Number(s)),
    });
    notify('반제 처리했습니다.');
    setSettling(null);
    setDetail(null);
    list.reload();
    pending.reload();
  }

  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;
  const pendingTotal = pending.data ? pending.data.total : 0;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['조회 거래내역', <Num value={total} />],
            ['반제 대기 예외', <Num value={pendingTotal} />],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>은행 거래내역</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="시작일" required>
            <DateInput value={fromDate} onChange={setFromDate} />
          </Field>
          <Field label="종료일" required>
            <DateInput value={toDate} onChange={setToDate} />
          </Field>
          <Field label="거래처 계좌">
            <LookupSelect table="partner_account" role={role} value={accountId} onChange={setAccountId} />
          </Field>
          <Field label="처리 구분">
            <Select value={processingType} onChange={setProcessingType} options={TYPES} />
          </Field>
        </Filters>
        {list.error ? <ErrorText text={list.error} /> : null}
        <Band total={total} />
        <DataTable
          rows={rows}
          empty="거래내역이 없습니다."
          onRowClick={(row) => setDetail(row)}
          columns={[
            { key: 'transactionAt', label: '거래일시', render: (r) => <DateText value={r['transactionAt']} time /> },
            { key: 'depositAmount', label: '입금액', render: (r) => <Num value={r['depositAmount']} /> },
            { key: 'withdrawalAmount', label: '출금액', render: (r) => <Num value={r['withdrawalAmount']} /> },
            { key: 'summary', label: '적요' },
            { key: 'counterpartyName', label: '상대 예금주명' },
            { key: 'processingType', label: '처리 구분', render: (r) => <Badge value={r['processingType']} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                r['processingType'] === '예외' ? (
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      openSettle(r);
                    }}
                  >
                    반제
                  </button>
                ) : null,
            },
          ]}
        />
        <Pager page={pageNo} size={20} total={total} onPage={setPageNo} />
      </section>
      <section className="box span-4">
        <h2>반제 대기</h2>
        {pending.error ? <ErrorText text={pending.error} /> : null}
        <DataTable
          rows={pending.data ? pending.data.items : []}
          empty="반제 대기 거래가 없습니다."
          onRowClick={(row) => openSettle(row)}
          columns={[
            { key: 'transactionAt', label: '거래일시', render: (r) => <DateText value={r['transactionAt']} /> },
            { key: 'counterpartyName', label: '상대 예금주명' },
            { key: 'depositAmount', label: '입금액', render: (r) => <Num value={r['depositAmount']} /> },
            { key: 'withdrawalAmount', label: '출금액', render: (r) => <Num value={r['withdrawalAmount']} /> },
          ]}
        />
      </section>
      {detail ? (
        <Drawer title="거래내역 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['거래일시', <DateText value={detail['transactionAt']} time />],
              ['입금액', <Num value={detail['depositAmount']} />],
              ['출금액', <Num value={detail['withdrawalAmount']} />],
              ['적요', String(detail['summary'] ?? '')],
              ['상대 예금주명', String(detail['counterpartyName'] ?? '')],
              ['처리 구분', <Badge value={detail['processingType']} />],
            ]}
          />
          {detail['processingType'] === '예외' ? (
            <button type="button" onClick={() => openSettle(detail)}>
              반제 처리
            </button>
          ) : null}
        </Drawer>
      ) : null}
      {settling ? (
        <Drawer title="예외 거래내역 반제 처리" onClose={() => setSettling(null)}>
          <Pairs
            items={[
              ['거래일시', <DateText value={settling['transactionAt']} time />],
              ['입금액', <Num value={settling['depositAmount']} />],
              ['출금액', <Num value={settling['withdrawalAmount']} />],
              ['상대 예금주명', String(settling['counterpartyName'] ?? '')],
            ]}
          />
          <Form onSubmit={settle} submit="반제 처리">
            <Field label="반제할 채권·채무 항목 ID 목록" required wide hint="쉼표로 구분해 여러 개 입력">
              <TextInput value={targetText} onChange={setTargetText} placeholder="예: 101, 102" />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
